/* TEAM CODE (owner: Tom - sound output and effects) - written by the BJT2 team, not generated by STM32CubeMX. */
/* Authors: Tom; Brendon (integrator) split the effect state into one union member per effect and doubled the echo delay to 240 ms (29-30 Oct 2026), and made the Autotune a hard tune to C major pentatonic with a 39 ms look-ahead (30 Oct 2026), with an AI coding assistant. */
/*
 * Tom's six sound effects: Autotune, Pitch up, Pitch down, Robot, Echo and
 * Reverb, on mono 16-bit PCM (plain signed sample values) at 48 kHz, in
 * blocks of 1..64 samples. Pure C (no HAL, no RTOS); the caller owns all
 * the state (AudioEffectsState, nothing is allocated). No task of its own:
 * FxRenderTask runs it through FxRender (FxRender/fx_render.c) to make one
 * effect file per effect ahead of time; TomTask runs no effect any more.
 * The host tests and Tools/audio_effect_demo.c run the same code on a PC.
 *
 * What each effect does to the sound (the maths is explained at each
 * effect's functions in audio_effects.c, and in pitch_detector.c and
 * pitch_shifter.c). A semitone is one step of the 12-note scale: a factor
 * of 2^(1/12) = 1.0595 in frequency.
 *   Autotune    hard-tunes the voice to a five-note scale (C major
 *               pentatonic: C D E G A), so speech comes out as a sing-song
 *               tune. The pitch detector (pitch_detector.c) measures the
 *               voice's pitch; the nearest note of the scale becomes the
 *               target; the pitch shifter (pitch_shifter.c, in hard-tune
 *               mode) moves the voice by target / pitch at once, up to
 *               about 1.5 semitones. The sound is played 39 ms late, so
 *               the pitch of each moment is already measured when it is
 *               played. A final 10 kHz low-pass softens clicks.
 *   Pitch up    the pitch shifter at a fixed ratio 2^(7/12) = 1.498: seven
 *               semitones (a musical fifth) higher, at the same speed.
 *   Pitch down  the same at 2^(-7/12) = 0.667: a fifth lower.
 *   Robot       narrows the voice to about 450 Hz - 2.4 kHz, then
 *               multiplies it by an 80 Hz tone plus its 160 Hz harmonic
 *               (ring modulation): every voice frequency f becomes f - 80
 *               and f + 80 Hz (and f -/+ 160 Hz). Those no longer fit one
 *               pitch, which gives the buzzy, metallic robot voice.
 *   Echo        adds the sound from 240 ms ago at 35 %; 30 % of it is fed
 *               back, so each repeat is 30 % of the one before.
 *   Reverb      four comb filters (repeating delays of 15-23 ms) side by
 *               side, then two all-pass diffusers: a dense tail of
 *               reflections that dies away in under a second, mixed with
 *               the dry sound.
 */
#ifndef AUDIO_EFFECTS_H
#define AUDIO_EFFECTS_H

#include <stddef.h>
#include <stdint.h>

#include "pitch_detector.h"
#include "pitch_shifter.h"

#define AUDIO_EFFECTS_SAMPLE_RATE_HZ          48000U
#define AUDIO_EFFECTS_MAX_BLOCK_SIZE          64U
#define AUDIO_EFFECTS_ECHO_DELAY_SAMPLES      11520U /* 240 ms at 48 kHz (was 120 ms) */
/* Autotune plays the sound 1888 samples (39.3 ms) late: the detector's
 * 2048-sample window (512 samples at 12 kHz = 2048 at 48 kHz) less the
 * shifter's average read delay of 160 samples (32 + 256 / 2). Then the
 * sound being played sits between the detector's two newest estimates, so
 * its pitch is known (see ae_autotune_pitch_now). */
#define AUDIO_EFFECTS_AUTOTUNE_SHIFTER_DELAY_SAMPLES 160U
#define AUDIO_EFFECTS_AUTOTUNE_LOOKAHEAD_SAMPLES     ((PITCH_DETECTOR_BUFFER_SIZE * PITCH_DETECTOR_DECIMATION) - AUDIO_EFFECTS_AUTOTUNE_SHIFTER_DELAY_SAMPLES)

/* Compact mono Schroeder-style reverb delay lengths.
 * In samples at 48 kHz: the combs 14.6, 16.9, 19.7 and 23.0 ms, the
 * all-passes 4.6 and 7.0 ms. All six are prime numbers, so the repeats of
 * different delays rarely land together and no single echo rhythm stands
 * out. */
#define AUDIO_EFFECTS_REVERB_COMB1_SAMPLES    701U
#define AUDIO_EFFECTS_REVERB_COMB2_SAMPLES    809U
#define AUDIO_EFFECTS_REVERB_COMB3_SAMPLES    947U
#define AUDIO_EFFECTS_REVERB_COMB4_SAMPLES    1103U
#define AUDIO_EFFECTS_REVERB_ALLPASS1_SAMPLES 223U
#define AUDIO_EFFECTS_REVERB_ALLPASS2_SAMPLES 337U

/* Pitch up / down: +7 semitones = x1.498, -7 = x0.667 (a musical fifth). */
#define AUDIO_EFFECTS_DEFAULT_PITCH_UP_SEMITONES    7.0f
#define AUDIO_EFFECTS_DEFAULT_PITCH_DOWN_SEMITONES -7.0f

/** Available playback-only audio effects. */
typedef enum
{
    AUDIO_EFFECT_AUTOTUNE = 0,
    AUDIO_EFFECT_PITCH_UP,
    AUDIO_EFFECT_PITCH_DOWN,
    AUDIO_EFFECT_ROBOT,
    AUDIO_EFFECT_ECHO,
    AUDIO_EFFECT_REVERB,
    AUDIO_EFFECT_COUNT
} AudioEffectMode;

/** Status values returned by public AudioEffects operations. */
typedef enum
{
    AUDIO_EFFECTS_STATUS_OK = 0,
    AUDIO_EFFECTS_STATUS_NULL_POINTER,
    AUDIO_EFFECTS_STATUS_INVALID_LENGTH,
    AUDIO_EFFECTS_STATUS_INVALID_MODE,
    AUDIO_EFFECTS_STATUS_BUFFER_ALIAS,
    AUDIO_EFFECTS_STATUS_INVALID_PARAMETER,
    AUDIO_EFFECTS_STATUS_PROCESSING_ERROR
} AudioEffectsStatus;

/** Read-only diagnostic information, mainly useful for autotune verification. */
typedef struct
{
    float detected_pitch_hz;
    float detector_confidence;
    float target_pitch_hz;
    float applied_pitch_ratio;
} AudioEffectsDiagnostics;

/*
 * Per-effect state. Each effect keeps only its own history here; the five
 * structs below share one block of memory (the union in AudioEffectsState).
 */

/** Autotune: pitch detector, look-ahead delay, pitch shifter and the note logic. */
typedef struct
{
    PitchDetector pitch_detector;
    PitchShifter pitch_shifter;
    int16_t lookahead[AUDIO_EFFECTS_AUTOTUNE_LOOKAHEAD_SAMPLES]; /* the input, 39 ms late, circular */
    uint16_t lookahead_index;     /* next slot to read and overwrite */
    int16_t delayed[AUDIO_EFFECTS_MAX_BLOCK_SIZE]; /* this block, 39 ms late (kept here, not on the task's stack) */
    float previous_pitch_hz;      /* the detector's estimate before the newest (0 = no reliable pitch) */
    float newest_pitch_hz;        /* the detector's newest estimate (0 = no reliable pitch) */
    float target_hz;              /* the scale note held now (0 = none yet) */
    float ratio_target;           /* pitch ratio handed to the shifter */
    float declick_output;         /* the de-click low-pass filter's last output */
    uint32_t unvoiced_samples;    /* samples since the last reliable pitch */
} AudioEffectsAutotuneState;

/** Pitch up and pitch down: only the pitch shifter. */
typedef struct
{
    PitchShifter pitch_shifter;
} AudioEffectsPitchState;

/** Robot: the 80 Hz ring-modulation oscillator and the speech-band filters. */
typedef struct
{
    float osc_sin;                /* oscillator output: sin and cos of its phase */
    float osc_cos;
    float osc_sin_delta;          /* sin and cos of one sample's phase step */
    float osc_cos_delta;
    float hp_alpha;               /* high-pass (450 Hz) coefficient */
    float lp_alpha;               /* low-pass (2.4 kHz) coefficient */
    float hp_prev_input;
    float hp_prev_output;
    float lp_output;              /* first low-pass stage */
    float lp_output2;             /* second low-pass stage */
} AudioEffectsRobotState;

/** Echo: one 240 ms circular delay line. */
typedef struct
{
    int16_t buffer[AUDIO_EFFECTS_ECHO_DELAY_SAMPLES];
    uint16_t index;               /* next sample to read and overwrite */
} AudioEffectsEchoState;

/** Reverb: four comb filters and two all-pass filters (delay lines). */
typedef struct
{
    int16_t comb1[AUDIO_EFFECTS_REVERB_COMB1_SAMPLES];
    int16_t comb2[AUDIO_EFFECTS_REVERB_COMB2_SAMPLES];
    int16_t comb3[AUDIO_EFFECTS_REVERB_COMB3_SAMPLES];
    int16_t comb4[AUDIO_EFFECTS_REVERB_COMB4_SAMPLES];
    int16_t allpass1[AUDIO_EFFECTS_REVERB_ALLPASS1_SAMPLES];
    int16_t allpass2[AUDIO_EFFECTS_REVERB_ALLPASS2_SAMPLES];
    uint16_t comb_index1;
    uint16_t comb_index2;
    uint16_t comb_index3;
    uint16_t comb_index4;
    uint16_t allpass_index1;
    uint16_t allpass_index2;
} AudioEffectsReverbState;

/**
 * Persistent state for all audio effects.
 *
 * The structure is intentionally caller-owned so the module has no dynamic
 * allocation and can be kept in static RAM on the STM32. State must persist
 * between consecutive blocks because the pitch detector, pitch shifter,
 * filters, echo and reverb all depend on earlier samples.
 *
 * Only ONE effect runs at a time, so the five per-effect states share one
 * block of memory (the union per_mode): only the member of the selected mode
 * is in use. Why: the 240 ms echo needs 23 KB on its own, and with a
 * separate copy of every effect's state (37.6 KB) the firmware no longer fit
 * in the STM32's 128 KB of RAM. The union is as big as its biggest member
 * (the echo), 23 072 B in all.
 *
 * The rule that makes this safe: Init, Reset and SetMode reset ONLY the
 * selected mode's member (plus the diagnostics). Writing any other member
 * would overwrite the selected effect's history, because they overlap.
 */
typedef struct
{
    AudioEffectMode mode;         /* the selected effect: which union member is in use */

    /* Fixed today, but exposed as state so a future UI can scale them. */
    float pitch_up_semitones;
    float pitch_down_semitones;

    AudioEffectsDiagnostics diagnostics;

    union
    {
        AudioEffectsAutotuneState autotune;  /* mode AUTOTUNE */
        AudioEffectsPitchState pitch;        /* modes PITCH_UP and PITCH_DOWN */
        AudioEffectsRobotState robot;        /* mode ROBOT */
        AudioEffectsEchoState echo;          /* mode ECHO */
        AudioEffectsReverbState reverb;      /* mode REVERB */
    } per_mode;
} AudioEffectsState;

/**
 * @brief Initialise an AudioEffectsState with default settings: AUTOTUNE
 *        selected, the pitch presets (+7 / -7 semitones), and the autotune
 *        history and the diagnostics cleared.
 * @param state Persistent state to initialise. NULL is safely ignored.
 */
void AudioEffects_Init(AudioEffectsState *state);

/**
 * @brief Clear the selected mode's DSP history (and the diagnostics) while
 *        preserving the selected mode and pitch presets.
 * @param state Persistent state to reset. NULL is safely ignored.
 */
void AudioEffects_Reset(AudioEffectsState *state);

/**
 * @brief Select the effect applied by AudioEffects_ProcessBlock(). A new
 *        mode starts with its history cleared; selecting the mode that is
 *        already selected changes nothing.
 * @param state Persistent DSP state.
 * @param mode Effect to select.
 * @return AUDIO_EFFECTS_STATUS_OK, NULL_POINTER or INVALID_MODE.
 */
AudioEffectsStatus AudioEffects_SetMode(AudioEffectsState *state, AudioEffectMode mode);

/**
 * @brief Read the currently selected effect.
 * @param state Persistent DSP state.
 * @return Selected mode, or AUTOTUNE as a safe default when state is NULL.
 */
AudioEffectMode AudioEffects_GetMode(const AudioEffectsState *state);

/**
 * @brief Configure scalable pitch-up or pitch-down amount.
 * @param state Persistent DSP state.
 * @param mode AUDIO_EFFECT_PITCH_UP or AUDIO_EFFECT_PITCH_DOWN.
 * @param semitones Pitch offset: 0..+12 for pitch-up, -12..0 for pitch-down.
 * @return Status indicating success or invalid state/mode/value.
 */
AudioEffectsStatus AudioEffects_SetPitchSemitones(AudioEffectsState *state,
                                                  AudioEffectMode mode,
                                                  float semitones);

/**
 * @brief Read the configured semitone offset for a pitch mode.
 * @param state Persistent DSP state.
 * @param mode AUDIO_EFFECT_PITCH_UP or AUDIO_EFFECT_PITCH_DOWN.
 * @return Configured offset, or 0.0f for NULL/unsupported modes.
 */
float AudioEffects_GetPitchSemitones(const AudioEffectsState *state,
                                     AudioEffectMode mode);

/**
 * @brief Convert a semitone interval to a frequency/pitch ratio.
 * @param semitones Signed semitone interval.
 * @return pow(2, semitones/12), or 1.0f for a non-finite value.
 */
float AudioEffects_SemitonesToRatio(float semitones);

/**
 * @brief Process one mono 16-bit PCM block using the currently selected effect.
 * @param state Persistent DSP state.
 * @param input Input sample buffer.
 * @param output Distinct output buffer; in-place processing is rejected.
 * @param sample_count Number of samples, from 1 to AUDIO_EFFECTS_MAX_BLOCK_SIZE.
 * @return AUDIO_EFFECTS_STATUS_OK or a specific validation/processing error.
 */
AudioEffectsStatus AudioEffects_ProcessBlock(AudioEffectsState *state,
                                             const int16_t *input,
                                             int16_t *output,
                                             size_t sample_count);

/**
 * @brief Read the latest diagnostic values without modifying DSP state.
 * @param state Persistent DSP state.
 * @return Latest diagnostics, or safe zero/default values when state is NULL.
 */
AudioEffectsDiagnostics AudioEffects_GetDiagnostics(const AudioEffectsState *state);

/**
 * @brief Quantise a positive input frequency to the nearest chromatic semitone.
 *        The Autotune now uses AudioEffects_ScaleTargetHz (five notes per
 *        octave); this one (all twelve) is kept for the tests and the tools.
 * @param input_hz Input frequency in hertz.
 * @return Nearest equal-tempered chromatic frequency, or 0.0f for invalid input.
 */
float AudioEffects_ChromaticTargetHz(float input_hz);

/**
 * @brief The nearest note of the Autotune's scale (C major pentatonic:
 *        C D E G A in every octave, A4 = 440 Hz).
 * @param input_hz Input frequency in hertz.
 * @return That note's frequency, or 0.0f for invalid input.
 */
float AudioEffects_ScaleTargetHz(float input_hz);

#endif
